css:
.orbital-loader {
  position: relative;
  width: 140px;
  height: 140px;
  margin: auto;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  perspective: 800px;
  transform-style: preserve-3d;
  box-sizing: border-box;
}

.orbital-loader *,
.orbital-loader *::before,
.orbital-loader *::after {
  box-sizing: border-box;
  transform-style: preserve-3d;
}

.core-system {
  position: absolute;
  width: 10px;
  height: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  animation: coreMasterCycle 22s cubic-bezier(0.4, 0, 0.2, 1) infinite;
}

.core-micro-center {
  position: absolute;
  width: 3px;
  height: 3px;
  background-color: #ffffff;
  border-radius: 50%;
  box-shadow: 0 0 6px 1px rgba(255, 255, 255, 0.9);
  animation: corePulse 3.73s ease-in-out infinite alternate;
}

.core-inner-glow {
  position: absolute;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: radial-gradient(
    circle,
    rgba(200, 235, 255, 0.9) 0%,
    rgba(255, 255, 255, 0) 70%
  );
  animation: coreBreathe 2.41s ease-in-out infinite alternate;
}

.core-thin-ring {
  position: absolute;
  width: 14px;
  height: 14px;
  border: 1px solid rgba(255, 255, 255, 0.6);
  border-radius: 50%;
  animation: coreRingRotate 4.12s linear infinite;
}

.core-secondary-ring {
  position: absolute;
  width: 22px;
  height: 22px;
  border: 1px dashed rgba(180, 220, 255, 0.35);
  border-radius: 50%;
  animation: coreRingRotateReverse 6.28s linear infinite;
}

.core-outer-ring {
  position: absolute;
  width: 32px;
  height: 32px;
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-top-color: rgba(255, 255, 255, 0.5);
  border-radius: 50%;
  animation: coreRingRotate 9.14s linear infinite;
}

.core-halo {
  position: absolute;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: radial-gradient(
    circle,
    rgba(160, 215, 255, 0.12) 0%,
    rgba(255, 255, 255, 0) 75%
  );
  animation: coreFluctuate 5.18s ease-in-out infinite alternate;
}

.pulse-system {
  position: absolute;
  width: 100%;
  height: 100%;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
}

.pulse-ring {
  position: absolute;
  border-radius: 50%;
  border: 1px solid rgba(210, 240, 255, 0.8);
  opacity: 0;
  width: 4px;
  height: 4px;
}

.pulse-ring-1 {
  animation: shockwavePulse 22s cubic-bezier(0.1, 0.8, 0.3, 1) infinite;
}

.pulse-ring-2 {
  animation: shockwavePulse 22s cubic-bezier(0.1, 0.8, 0.3, 1) infinite 0.18s;
}

.pulse-ring-3 {
  animation: shockwavePulse 22s cubic-bezier(0.1, 0.8, 0.3, 1) infinite 0.36s;
}

.orbit-system {
  position: absolute;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
}

.orbit-path {
  position: absolute;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  pointer-events: none;
}

.orbit-object-wrapper {
  position: absolute;
  width: 100%;
  height: 100%;
  border-radius: 50%;
}

.orbit-object {
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translate(-50%, -50%);
}

.orbit-1 {
  width: 90px;
  height: 90px;
  transform: rotateX(68deg) rotateY(12deg) rotateZ(0deg);
  animation: orbitMaster1 22s ease-in-out infinite;
}

.orbit-1 .orbit-path {
  border: 1px solid rgba(255, 255, 255, 0.22);
  background: radial-gradient(
    circle,
    transparent 60%,
    rgba(255, 255, 255, 0.03) 100%
  );
}

.orbit-1 .orbit-object-wrapper {
  animation: spinClockwise 3.73s linear infinite;
}

.orbit-1 .obj-circle {
  width: 4px;
  height: 4px;
  background-color: #ffffff;
  border-radius: 50%;
  box-shadow: 0 0 5px #ffffff;
}

.orbit-1 .object-trail {
  position: absolute;
  top: 50%;
  left: 100%;
  width: 18px;
  height: 1px;
  background: linear-gradient(90deg, rgba(255, 255, 255, 0.4), transparent);
  transform-origin: left center;
  transform: translateY(-50%) rotate(180deg);
}

.orbit-2 {
  width: 114px;
  height: 114px;
  transform: rotateX(58deg) rotateY(-28deg) rotateZ(25deg);
  animation: orbitMaster2 22s ease-in-out infinite;
}

.orbit-2 .orbit-path {
  border: 1px solid rgba(220, 230, 240, 0.14);
  mask: radial-gradient(circle, transparent 50%, #000 100%),
    conic-gradient(from 0deg, #000 0deg, transparent 270deg, #000 360deg);
  -webkit-mask: conic-gradient(
    from 45deg,
    rgba(0, 0, 0, 0.8) 0deg,
    transparent 180deg,
    rgba(0, 0, 0, 0.8) 360deg
  );
}

.orbit-2 .orbit-object-wrapper {
  animation: spinCounterClockwise 5.18s linear infinite;
}

.orbit-2 .obj-ring {
  width: 5px;
  height: 5px;
  border: 1px solid rgba(255, 255, 255, 0.9);
  border-radius: 50%;
  animation: keepUpright2 5.18s linear infinite;
}

.orbit-3 {
  width: 54px;
  height: 54px;
  transform: rotateX(76deg) rotateY(38deg) rotateZ(-15deg);
  animation: orbitMaster3 22s ease-in-out infinite;
}

.orbit-3 .orbit-path {
  border: 1px dashed rgba(255, 255, 255, 0.28);
}

.orbit-3 .orbit-object-wrapper {
  animation: spinClockwise 2.31s linear infinite;
}

.orbit-3 .obj-bright-point {
  width: 3px;
  height: 3px;
  background-color: #e0f2ff;
  border-radius: 50%;
  box-shadow: 0 0 6px 1px #a6daff;
}

.orbit-4 {
  width: 132px;
  height: 132px;
  transform: rotateX(42deg) rotateY(-52deg) rotateZ(40deg);
  animation: orbitMaster4 22s ease-in-out infinite;
}

.orbit-4 .orbit-path {
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.orbit-4 .orbit-object-wrapper {
  animation: spinCounterClockwise 9.26s linear infinite;
}

.orbit-4 .obj-diamond {
  width: 4px;
  height: 4px;
  background-color: rgba(230, 240, 255, 0.85);
  transform: translate(-50%, -50%) rotate(45deg);
  box-shadow: 0 0 3px rgba(255, 255, 255, 0.5);
}

.orbit-5 {
  width: 102px;
  height: 102px;
  transform: rotateX(62deg) rotateY(65deg) rotateZ(-45deg);
  animation: orbitMaster5 22s ease-in-out infinite;
}

.orbit-5 .orbit-path {
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-left-color: rgba(255, 255, 255, 0.35);
}

.orbit-5 .orbit-object-wrapper {
  animation: spinCounterClockwise 7.87s linear infinite;
}

.orbit-5 .obj-line {
  width: 6px;
  height: 1px;
  background-color: #ffffff;
  box-shadow: 0 0 4px rgba(255, 255, 255, 0.8);
  animation: selfRotate 3.1s linear infinite;
}

.orbit-6 {
  width: 122px;
  height: 122px;
  transform: rotateX(84deg) rotateY(-78deg) rotateZ(10deg);
  animation: orbitMaster6 22s ease-in-out infinite;
}

.orbit-6 .orbit-path {
  border: 1px solid rgba(200, 210, 225, 0.06);
  border-top: 1px solid rgba(255, 255, 255, 0.25);
}

.orbit-6 .orbit-object-wrapper {
  animation: spinClockwise 11.13s linear infinite;
}

.orbit-6 .obj-square {
  width: 3px;
  height: 3px;
  background-color: rgba(210, 235, 255, 0.9);
  animation: keepUpright6 11.13s linear infinite;
}

.orbit-7 {
  width: 138px;
  height: 120px;
  transform: rotateX(48deg) rotateY(22deg) rotateZ(-65deg) skewX(8deg);
  animation: orbitMaster7 22s ease-in-out infinite;
}

.orbit-7 .orbit-path {
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-style: double;
}

.orbit-7 .orbit-object-wrapper {
  animation: spinCounterClockwise 13.62s linear infinite;
}

.orbit-7 .obj-fragment {
  width: 5px;
  height: 4px;
  background-color: rgba(240, 248, 255, 0.85);
  clip-path: polygon(0% 0%, 100% 20%, 80% 100%, 10% 70%);
  animation: selfRotate 4.5s linear infinite reverse;
}

.particle-system {
  position: absolute;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.particle {
  position: absolute;
  background-color: rgba(255, 255, 255, 0.7);
  border-radius: 50%;
  animation: particleFloat 6s ease-in-out infinite alternate;
}

.p1 {
  width: 1.5px;
  height: 1.5px;
  top: 22%;
  left: 30%;
  animation-delay: 0.2s;
  opacity: 0.4;
}
.p2 {
  width: 2px;
  height: 2px;
  top: 75%;
  left: 20%;
  animation-delay: 1.1s;
  opacity: 0.6;
}
.p3 {
  width: 1px;
  height: 1px;
  top: 15%;
  left: 70%;
  animation-delay: 0.7s;
  opacity: 0.3;
}
.p4 {
  width: 2px;
  height: 2px;
  top: 80%;
  left: 75%;
  animation-delay: 2.3s;
  opacity: 0.5;
}
.p5 {
  width: 1.5px;
  height: 1.5px;
  top: 45%;
  left: 12%;
  animation-delay: 1.8s;
  opacity: 0.6;
}
.p6 {
  width: 1px;
  height: 1px;
