  left: 88%;
  animation-delay: 3.1s;
  opacity: 0.4;
}
.p7 {
  width: 2.5px;
  height: 2.5px;
  top: 32%;
  left: 82%;
  animation-delay: 0.4s;
  opacity: 0.7;
  box-shadow: 0 0 3px #fff;
}
.p8 {
  width: 1px;
  height: 1px;
  top: 68%;
  left: 35%;
  animation-delay: 2.9s;
  opacity: 0.3;
}
.p9 {
  width: 1.5px;
  height: 1.5px;
  top: 88%;
  left: 45%;
  animation-delay: 1.4s;
  opacity: 0.5;
}
.p10 {
  width: 2px;
  height: 2px;
  top: 10%;
  left: 48%;
  animation-delay: 3.5s;
  opacity: 0.6;
}
.p11 {
  width: 1px;
  height: 1px;
  top: 38%;
  left: 25%;
  animation-delay: 0.9s;
  opacity: 0.4;
}
.p12 {
  width: 1.5px;
  height: 1.5px;
  top: 62%;
  left: 78%;
  animation-delay: 2.1s;
  opacity: 0.5;
}
.p13 {
  width: 2px;
  height: 2px;
  top: 28%;
  left: 60%;
  animation-delay: 1.6s;
  opacity: 0.3;
}
.p14 {
  width: 1px;
  height: 1px;
  top: 72%;
  left: 58%;
  animation-delay: 3.8s;
  opacity: 0.4;
}
.p15 {
  width: 2px;
  height: 2px;
  top: 55%;
  left: 18%;
  animation-delay: 2.7s;
  opacity: 0.6;
}

.energy-fragments {
  position: absolute;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.energy-fragment {
  position: absolute;
  width: 3px;
  height: 3px;
  background-color: rgba(180, 230, 255, 0.9);
  border-radius: 50%;
  box-shadow: 0 0 5px rgba(180, 230, 255, 0.8);
}

.ef1 {
  top: 50%;
  left: 50%;
  animation: energyFragmentMotion1 22s ease-in-out infinite;
}

.ef2 {
  top: 50%;
  left: 50%;
  animation: energyFragmentMotion2 22s ease-in-out infinite;
}

.ef3 {
  top: 50%;
  left: 50%;
  animation: energyFragmentMotion3 22s ease-in-out infinite;
}

@keyframes spinClockwise {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}

@keyframes spinCounterClockwise {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(-360deg);
  }
}

@keyframes selfRotate {
  0% {
    transform: translate(-50%, -50%) rotate(0deg);
  }
  100% {
    transform: translate(-50%, -50%) rotate(360deg);
  }
}

@keyframes keepUpright2 {
  0% {
    transform: translate(-50%, -50%) rotate(0deg);
  }
  100% {
    transform: translate(-50%, -50%) rotate(360deg);
  }
}

@keyframes keepUpright6 {
  0% {
    transform: translate(-50%, -50%) rotate(0deg);
  }
  100% {
    transform: translate(-50%, -50%) rotate(-360deg);
  }
}

@keyframes corePulse {
  0% {
    transform: scale(0.85);
    opacity: 0.7;
  }
  100% {
    transform: scale(1.25);
    opacity: 1;
    box-shadow: 0 0 9px 2px rgba(255, 255, 255, 1);
  }
}

@keyframes coreBreathe {
  0% {
    transform: scale(0.9);
    opacity: 0.4;
  }
  100% {
    transform: scale(1.4);
    opacity: 0.9;
  }
}

@keyframes coreFluctuate {
  0% {
    transform: scale(0.8) rotate(0deg);
    opacity: 0.2;
  }
  50% {
    opacity: 0.6;
  }
  100% {
    transform: scale(1.2) rotate(180deg);
    opacity: 0.3;
  }
}

@keyframes coreRingRotate {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}

@keyframes coreRingRotateReverse {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(-360deg);
  }
}

@keyframes particleFloat {
  0% {
    transform: translate(0, 0) scale(0.8);
  }
  50% {
    transform: translate(3px, -4px) scale(1.2);
  }
  100% {
    transform: translate(-2px, 3px) scale(0.9);
  }
}

@keyframes shockwavePulse {
  0% {
    width: 4px;
    height: 4px;
    opacity: 0;
    border-width: 2px;
  }
  85% {
    opacity: 0;
  }
  86% {
    width: 6px;
    height: 6px;
    opacity: 1;
    border-color: rgba(255, 255, 255, 1);
    border-width: 2px;
  }
  92% {
    width: 130px;
    height: 130px;
    opacity: 0.4;
    border-color: rgba(160, 220, 255, 0.6);
    border-width: 1px;
  }
  96% {
    width: 170px;
    height: 170px;
    opacity: 0;
    border-width: 0.5px;
  }
  100% {
    width: 4px;
    height: 4px;
    opacity: 0;
  }
}

@keyframes coreMasterCycle {
  0% {
    transform: scale(0.3);
    opacity: 0.2;
  }
  6% {
    transform: scale(1);
    opacity: 1;
  }
  58% {
    transform: scale(1);
    filter: brightness(1);
  }
  64% {
    transform: scale(1.15);
    filter: brightness(1.4);
  }
  68% {
    transform: scale(0.95);
    filter: brightness(1.1);
  }
  74% {
    transform: scale(1.3);
    filter: brightness(1.8);
  }
  80% {
    transform: scale(0.15);
    filter: brightness(0.5);
    opacity: 0.9;
  }
  84% {
    transform: scale(0.05);
    filter: brightness(0.2);
    opacity: 0.3;
  }
  85.5% {
    transform: scale(0);
    opacity: 0;
  }
  86% {
    transform: scale(2.2);
    filter: brightness(2.5);
    opacity: 1;
  }
  90% {
    transform: scale(0.9);
    filter: brightness(1.2);
    opacity: 0.9;
  }
  95% {
    transform: scale(1);
    filter: brightness(1);
    opacity: 1;
  }
  100% {
    transform: scale(1);
    opacity: 1;
  }
}

@keyframes orbitMaster1 {
  0% {
    transform: rotateX(68deg) rotateY(12deg) rotateZ(0deg) scale(0.2);
    opacity: 0;
  }
  8% {
    transform: rotateX(68deg) rotateY(12deg) rotateZ(0deg) scale(1);
    opacity: 1;
  }
  58% {
    transform: rotateX(68deg) rotateY(12deg) rotateZ(0deg) scale(1);
    opacity: 1;
  }
  64% {
    transform: rotateX(68deg) rotateY(12deg) rotateZ(0deg) scale(1.05);
  }
  68% {
    transform: rotateX(0deg) rotateY(0deg) rotateZ(0deg) scale(1);
  }
  74% {
    transform: rotateX(30deg) rotateY(40deg) rotateZ(90deg) scale(1.1);
    opacity: 0.9;
  }
  81% {
    transform: rotateX(68deg) rotateY(12deg) rotateZ(180deg) scale(0.15);
    opacity: 0.3;
  }
  85% {
    transform: scale(0);
    opacity: 0;
  }
  88% {
    transform: rotateX(68deg) rotateY(12deg) rotateZ(0deg) scale(1.3);
    opacity: 0.6;
  }
  94% {
    transform: rotateX(68deg) rotateY(12deg) rotateZ(0deg) scale(0.98);
    opacity: 1;
  }
  100% {
    transform: rotateX(68deg) rotateY(12deg) rotateZ(0deg) scale(1);
    opacity: 1;
  }
}

@keyframes orbitMaster2 {
  0% {
    transform: rotateX(58deg) rotateY(-28deg) rotateZ(25deg) scale(0);
    opacity: 0;
  }
  11% {
    transform: rotateX(58deg) rotateY(-28deg) rotateZ(25deg) scale(1);
    opacity: 0.85;
  }
  58% {
    transform: rotateX(58deg) rotateY(-28deg) rotateZ(25deg) scale(1);
    opacity: 0.85;
  }
  64% {
    transform: rotateX(58deg) rotateY(-28deg) rotateZ(25deg) scale(1.08);
  }
  68% {
    transform: rotateX(0deg) rotateY(0deg) rotateZ(0deg) scale(1);
  }
  75% {
    transform: rotateX(-50deg) rotateY(20deg) rotateZ(-45deg) scale(0.8);
    opacity: 1;
  }
  82% {
    transform: rotateX(58deg) rotateY(-28deg) rotateZ(90deg) scale(0.1);
    opacity: 0.2;
  }
  85% {
    transform: scale(0);
    opacity: 0;
  }
  89% {
    transform: rotateX(58deg) rotateY(-28deg) rotateZ(25deg) scale(1.25);
    opacity: 0.5;
  }
  95% {
    transform: rotateX(58deg) rotateY(-28deg) rotateZ(25deg) scale(1);
    opacity: 0.85;
  }
  100% {
    transform: rotateX(58deg) rotateY(-28deg) rotateZ(25deg) scale(1);
    opacity: 0.85;
  }
}

@keyframes orbitMaster3 {
  0% {
    transform: rotateX(76deg) rotateY(38deg) rotateZ(-15deg) scale(0);
    opacity: 0;
  }
  6% {
    transform: rotateX(76deg) rotateY(38deg) rotateZ(-15deg) scale(1);
    opacity: 1;
  }
  58% {
    transform: rotateX(76deg) rotateY(38deg) rotateZ(-15deg) scale(1);
    opacity: 1;
  }
  64% {
    transform: rotateX(76deg) rotateY(38deg) rotateZ(-15deg) scale(1.1);
  }
  68% {
    transform: rotateX(0deg) rotateY(0deg) rotateZ(0deg) scale(1);
  }
  73% {
    transform: rotateX(80deg) rotateY(-10deg) rotateZ(30deg) scale(1.2);
  }
  80% {
    transform: rotateX(76deg) rotateY(38deg) rotateZ(0deg) scale(0.08);
    opacity: 0.4;
  }
  85% {
    transform: scale(0);
    opacity: 0;
  }
  87% {
    transform: rotateX(76deg) rotateY(38deg) rotateZ(-15deg) scale(1.4);
    opacity: 0.8;
  }
  92% {
    transform: rotateX(76deg) rotateY(38deg) rotateZ(-15deg) scale(0.95);
    opacity: 1;
  }
  100% {
    transform: rotateX(76deg) rotateY(38deg) rotateZ(-15deg) scale(1);
    opacity: 1;
  }
}

@keyframes orbitMaster4 {
  0% {
    transform: rotateX(42deg) rotateY(-52deg) rotateZ(40deg) scale(0);
    opacity: 0;
  }
  14% {
    transform: rotateX(42deg) rotateY(-52deg) rotateZ(40deg) scale(1);
    opacity: 0.7;
  }
  58% {
    transform: rotateX(42deg) rotateY(-52deg) rotateZ(40deg) scale(1);
    opacity: 0.7;
  }
  64% {
    transform: rotateX(42deg) rotateY(-52deg) rotateZ(40deg) scale(1.04);
  }
  68% {
    transform: rotateX(0deg) rotateY(0deg) rotateZ(0deg) scale(1);
  }
  76% {
    transform: rotateX(-20deg) rotateY(-80deg) rotateZ(10deg) scale(0.7);
    opacity: 0.9;
  }
  83% {
    transform: rotateX(42deg) rotateY(-52deg) rotateZ(0deg) scale(0.05);
    opacity: 0.1;
  }
  85% {
    transform: scale(0);
    opacity: 0;
  }
  90% {
    transform: rotateX(42deg) rotateY(-52deg) rotateZ(40deg) scale(1.2);
    opacity: 0.4;
  }
  96% {
    transform: rotateX(42deg) rotateY(-52deg) rotateZ(40deg) scale(1);
    opacity: 0.7;
  }
  100% {
    transform: rotateX(42deg) rotateY(-52deg) rotateZ(40deg) scale(1);
    opacity: 0.7;
  }
}

@keyframes orbitMaster5 {
  0% {
    transform: rotateX(62deg) rotateY(65deg) rotateZ(-45deg) scale(0);
    opacity: 0;
  }
  10% {
    transform: rotateX(62deg) rotateY(65deg) rotateZ(-45deg) scale(1);
    opacity: 0.8;
  }
  58% {
    transform: rotateX(62deg) rotateY(65deg) rotateZ(-45deg) scale(1);
    opacity: 0.8;
  }
  64% {
    transform: rotateX(62deg) rotateY(65deg) rotateZ(-45deg) scale(1.06);
  }
  68% {
    transform: rotateX(0deg) rotateY(0deg) rotateZ(0deg) scale(1);
  }
  74% {
    transform: rotateX(45deg) rotateY(20deg) rotateZ(-90deg) scale(1.15);
  }
  81% {
    transform: rotateX(62deg) rotateY(65deg) rotateZ(0deg) scale(0.12);
    opacity: 0.2;
  }
  85% {
    transform: scale(0);
    opacity: 0;
  }
  88.5% {
    transform: rotateX(62deg) rotateY(65deg) rotateZ(-45deg) scale(1.35);
    opacity: 0.6;
